/* ==========================================================================
   Build Planner v2 · skill tree data
   --------------------------------------------------------------------------
   Edit this file to add or change trees. Run  node tools/validate.mjs  after
   editing (GitHub runs it on every push too).

   Tree:  { id, n:name, c:category, r:rarity, ty:type, sk:[8 skills],
            cu:[curseName, curseText, [[label,text],...]]   (cursed trees only)
            no:[[label,text],...]                           (extra tree notes) }
     id   stays forever: share links store it. If you must rename an id, add
          the old one to BP.TREE_ALIASES below so old links still load.
     c    melee | ranged | magic | support | auxiliary | cursed
     r    Common | Uncommon | Rare | Legendary
     ty   "Main Class Tree" (can be the birth tree) | "Auxiliary Tree" | "Cursed Tree"

   Skill: { t:tier (total points in this tree to unlock it), n:name, g:[tags],
            x:text, c:1 (capstone),
            s:[[label,text],...]            sub-rules (bulleted under the text)
            f:[[circles,form,text,passive?],...]   forms (Archmage)
            h:[[side,name,[tags],text],...] Form skill halves (Lycanthropy)
            ap:[...]                        what it applies to targets, for the
                                            "Applies" panel (see BP.APPLIES)
            img:"url"                       optional icon override }
   Icons: icons/<tree id>/01.webp = tree icon, 02…09.webp = skills in order.
   Skill names in a tree's text are hover links automatically (same tree);
   mechanics shared between trees are listed in data/keywords.js.
   ========================================================================== */
window.BP = window.BP || {};

/* Old tree id → current id. Add an entry whenever you rename an id. */
BP.TREE_ALIASES = {
  /* "old_id": "new_id", */
};

